    /// <summary>All entity sets with a full field list — the studio shows a template for each, staged or not.</summary>
    public static IReadOnlyCollection<string> Entities { get; } =
        StandardFields.Keys.Concat(CuratedFields.Keys).OrderBy(k => k, StringComparer.OrdinalIgnoreCase).ToList();

    /// <summary>Every field an entity can carry: canonical schema first, then tenant customs; staged fields union on top at read time.</summary>
    public static IReadOnlyList<string> FieldsFor(string entitySet)
    {
        if (CuratedFields.TryGetValue(entitySet, out var curated))
        {
            return curated;
        }
        if (StandardFields.TryGetValue(entitySet, out var std))
        {
            if (entitySet == "ReleasedProductsV2")
            {
                return std.Where(f => f != "@@SHAM@@").Concat(ShamProductFields).ToList();
            }
            return std;
        }
        return System.Array.Empty<string>();
    }
